#include "can_private.h"

/*==========================================================================*/
/*      D E F I N E S  -  E N U M E R A T I O N S  -  T Y P E D E F S       */
/*==========================================================================*/

/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/

/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

void can_irq_service_tx (Can_Tx can_tx , UInt32 bus_status)
{
  /// Disable TX IRQ ///

  can_tx->can_dev->io_base [CANIER] &= ~ can_tx_bit_table [can_tx->can_tx_id].canier_tie ;

  #define BIT(z) ((UInt32) 1 << (z))

  /// Signal arbitration lost ///

  if (bus_status & BIT (6))
    {
      os_evt_signal_i (can_tx->evt_tx , CAN_IRQ_TX_LOST_ARBITRATION) ;

      return ;
    }

  /// Signal TX bus error ///

  if ((bus_status & BIT (7)) && ! (bus_status & BIT (21)))
    {
      os_evt_signal_i (can_tx->evt_tx , CAN_IRQ_TX_BUS_ERROR) ;

      return ;
    }

  /// Signal TX buff is free ///

  os_evt_signal_i (can_tx->evt_tx , CAN_IRQ_TX_READY) ;

  #undef  BIT
}

